def _normalize_patch_radius(patch_radius):
    """Return ``patch_radius`` as a length-3 tuple of integers.

    Patch2Self accepts a single scalar (used for all three spatial axes) or a
    sequence of length 1 or 3.  Normalizing here keeps the validation and the
    denoising paths consistent for scalars, lists, tuples and arrays.
    """
    if np.isscalar(patch_radius) or (
        isinstance(patch_radius, np.ndarray) and patch_radius.ndim == 0
    ):
        radius = int(patch_radius)
        return (radius, radius, radius)

    try:
        patch_radius = tuple(int(radius) for radius in patch_radius)
    except TypeError as exc:
        raise ValueError(
            "patch_radius should be a scalar or a sequence of length 1 or 3."
        ) from exc

    if len(patch_radius) == 1:
        patch_radius = patch_radius * 3
    elif len(patch_radius) != 3:
        raise ValueError("patch_radius should have length 1 or 3")

    return patch_radius

